"lu-xun": {"n":"Lu Xun","c":["A Chinese writer (魯迅)","Lived 1881–1936","The True Story of Ah Q","Diary of a Madman, among the first stories in everyday Chinese","Gave up medicine in Japan to heal his country with writing"],"p":"Lu Xun"},
"li-ka-shing": {"n":"Li Ka-shing","c":["A Hong Kong businessman (李嘉誠)","Born 1928 in Chaozhou","Began with a factory making plastic flowers","Built CK Hutchison: ports, telephones, Watsons and Superdrug","Superman, Hong Kong calls him; long its richest man"],"p":"Li Ka-shing"},
"lee-kuan-yew": {"n":"Lee Kuan Yew","c":["The first prime minister of Singapore (李光耀)","Lived 1923–2015","Led Singapore from 1959 to 1990","Made a port town one of the world's richest countries","Studied law at Cambridge"],"p":"Lee Kuan Yew"},
"laozi": {"n":"Laozi","c":["A Chinese philosopher (老子)","Lived in the 6th century BC, by tradition","Wrote the Tao Te Ching","The founder of Taoism: the Way, and acting without forcing","Rode west on an ox and vanished, the story goes"],"p":"Laozi"},
"cosimo-de-medici": {"n":"Cosimo de' Medici","c":["A banker who ruled Florence","Lived 1389–1464","Head of the Medici Bank, banker to the popes","Patron of Brunelleschi, Donatello and Fra Angelico","Called Pater Patriae, father of his country"],"p":"Cosimo de' Medici"},
"jakob-fugger": {"n":"Jakob Fugger","c":["A merchant and banker of Augsburg","Lived 1459–1525","Perhaps the richest man there has ever been: Jakob the Rich","Lent the money that made Charles V emperor","Built the Fuggerei, homes for the poor still let for under a euro a year"],"p":"Jakob Fugger"},
