"mayer-amschel-rothschild": {"n":"Mayer Amschel Rothschild","c":["A banker of Frankfurt","Lived 1744–1812","Founded the Rothschilds' bank","Began as a dealer in rare coins","Sent his five sons to banks in Frankfurt, London, Paris, Vienna and Naples"],"p":"Mayer Amschel Rothschild"},
"william-jardine": {"n":"William Jardine","c":["A Scottish merchant in China","Lived 1784–1843","Founded Jardine Matheson with James Matheson in Canton, in 1832","A ship's surgeon first, for the East India Company","Made his fortune smuggling opium; urged Britain into the First Opium War"],"p":"William Jardine (merchant)"},
"andrew-carnegie": {"n":"Andrew Carnegie","c":["A Scottish-American steel magnate","Lived 1835–1919","Sold Carnegie Steel to J. P. Morgan, who made it U.S. Steel","Gave most of his fortune away: libraries, Carnegie Hall","“The man who dies thus rich dies disgraced”"],"p":"Andrew Carnegie"},
"marcus-samuel": {"n":"Marcus Samuel","c":["A British merchant","Lived 1853–1927","Founded Shell, named after his father's trade in seashells","Sent the first tanker through the Suez Canal, the Murex, in 1892","Joined Shell with Royal Dutch in 1907","Lord Mayor of London"],"p":"Marcus Samuel, 1st Viscount Bearsted"},
"calouste-gulbenkian": {"n":"Calouste Gulbenkian","c":["An Armenian oil businessman","Lived 1869–1955; born in Istanbul","Mr Five Per Cent: kept 5% of the Iraq Petroleum Company","Drew the Red Line agreement round the old Ottoman lands","His art fills a museum in Lisbon, where he died"],"p":"Calouste Gulbenkian"},
"marc-rich": {"n":"Marc Rich","c":["A commodity trader, born in Antwerp","Lived 1934–2013","A father of the spot market in oil","Founded Marc Rich + Co, which became Glencore","Fled to Switzerland when charged in the US; pardoned by Bill Clinton in 2001"],"p":"Marc Rich"},
"christiaan-huygens": {"n":"Christiaan Huygens","c":["A Dutch scientist","Lived 1629–1695","Built the first pendulum clock, in 1656","Said that light is a wave","Found Saturn's moon Titan, and saw its rings for what they are"],"p":"Christiaan Huygens"},
"abraham-louis-breguet": {"n":"Abraham-Louis Breguet","c":["A Swiss-born watchmaker in Paris","Lived 1747–1823","Invented the tourbillon","Made watches for Marie Antoinette and Napoleon","The Breguet brand still bears his name"],"p":"Abraham-Louis Breguet"},
