"nicolas-hayek": {"n":"Nicolas Hayek","c":["A Lebanese-born Swiss businessman","Lived 1928–2010","Saved the Swiss watch industry from cheap quartz","Founded the Swatch Group","Helped begin the Smart car"],"p":"Nicolas Hayek"},
"earl-of-sandwich": {"n":"The Earl of Sandwich","a":["The 4th Earl of Sandwich"],"c":["John Montagu, a British statesman","Lived 1718–1792","The sandwich is named after him","Ate beef between bread so as not to leave the card table, the story goes","First Lord of the Admiralty; Cook named the Sandwich Islands after him"],"p":"John Montagu, 4th Earl of Sandwich"},
"charles-grey": {"n":"Earl Grey","a":["Charles Grey, 2nd Earl Grey"],"c":["Charles Grey, a British prime minister","Lived 1764–1845","Earl Grey tea, with bergamot, is named after him","Passed the Great Reform Act of 1832","His government abolished slavery in the British Empire, in 1833"],"p":"Charles Grey, 2nd Earl Grey"},
"lord-raglan": {"n":"Lord Raglan","c":["FitzRoy Somerset, a British field marshal","Lived 1788–1855","Commanded the British in the Crimean War","The raglan sleeve is named after him","Lost an arm at Waterloo"],"p":"FitzRoy Somerset, 1st Baron Raglan"},
"earl-of-cardigan": {"n":"The Earl of Cardigan","a":["The 7th Earl of Cardigan"],"c":["James Brudenell, a British general","Lived 1797–1868","Led the Charge of the Light Brigade in the Crimean War","The cardigan is named after him","Into the valley of Death rode the six hundred, Tennyson wrote"],"p":"James Brudenell, 7th Earl of Cardigan"},
"duke-of-windsor": {"n":"The Duke of Windsor","a":["Edward VIII"],"c":["King Edward VIII of Britain, who gave up the throne","Lived 1894–1972","Abdicated in 1936 to marry Wallis Simpson, an American divorcée","The Windsor knot is named after him","His brother became King George VI"],"p":"Edward VIII"},
"princess-therese": {"n":"Princess Therese","c":["A German princess who became queen of Bavaria","Lived 1792–1854","Her wedding to Ludwig I in 1810 began the Oktoberfest","The Theresienwiese in Munich, where it's held, is named after her","Mother of King Otto of Greece"],"p":"Therese of Saxe-Hildburghausen"},
"william-the-conqueror": {"n":"William the Conqueror","c":["A duke of Normandy who became king of England","Lived about 1028–1087","Won the Battle of Hastings in 1066","The Bayeux Tapestry tells the story","Had the Domesday Book drawn up","Built the Tower of London"],"p":"William the Conqueror"},
"robert-the-bruce": {"n":"Robert the Bruce","c":["A king of Scotland","Lived 1274–1329","Beat the English at Bannockburn in 1314","Took heart from a spider trying again and again, the story goes","His heart was carried on crusade, and buried at Melrose Abbey"],"p":"Robert the Bruce"},
"richard-iii": {"n":"Richard III","c":["A king of England, the last of the House of York","Lived 1452–1485","Fell at Bosworth, the end of the Wars of the Roses","His bones were found under a car park in Leicester in 2012","Shakespeare's villain: “A horse! A horse! My kingdom for a horse!”","Suspected of killing his nephews, the princes in the Tower"],"p":"Richard III of England"},
"mary-queen-of-scots": {"n":"Mary, Queen of Scots","a":["Mary Queen of Scots"],"c":["A queen of Scotland","Lived 1542–1587","Queen at six days old; grew up at the French court, and was briefly its queen","Kept prisoner nineteen years by her cousin Elizabeth I, then executed","Her son James became king of England and Scotland"],"p":"Mary, Queen of Scots"},
"robert-burns": {"n":"Robert Burns","c":["Scotland's national poet","Lived 1759–1796","Wrote Auld Lang Syne, sung at New Year","To a Mouse: the best-laid schemes o' mice an' men","Remembered on Burns Night, with haggis and whisky"],"p":"Robert Burns"},
"walter-scott": {"n":"Walter Scott","c":["A Scottish novelist and poet","Lived 1771–1832","Ivanhoe and Rob Roy","Began the historical novel","Edinburgh's Waverley station is named after his novels","The Scott Monument in Edinburgh"],"p":"Walter Scott"},
"robert-louis-stevenson": {"n":"Robert Louis Stevenson","c":["A Scottish novelist","Lived 1850–1894","Treasure Island: Long John Silver","Strange Case of Dr Jekyll and Mr Hyde","Kidnapped","Died on Samoa"],"p":"Robert Louis Stevenson"},
"ada-lovelace": {"n":"Ada Lovelace","c":["An English mathematician","Lived 1815–1852","Wrote the first computer program, for Babbage's Analytical Engine","Daughter of the poet Lord Byron","A programming language, Ada, is named after her"],"p":"Ada Lovelace"},
"henry-the-lion": {"n":"Henry the Lion","c":["A German duke of Saxony and Bavaria","Lived about 1129–1195","Founded Munich in 1158","Refounded Lübeck as a trading town","Fell out with his cousin, the Emperor Frederick Barbarossa","His bronze lion stands in Brunswick"],"p":"Henry the Lion"},
"frederick-the-great": {"n":"Frederick the Great","c":["A king of Prussia","Lived 1712–1786","Made Prussia a great power in the Seven Years' War","Played the flute and wrote music for it","Built Sanssouci, his summer palace at Potsdam","Brought the potato to Prussia: people leave potatoes on his grave"],"p":"Frederick the Great"},
