"ludwig-ii": {"n":"Ludwig II of Bavaria","a":["Ludwig II"],"c":["A king of Bavaria, the fairy-tale king","Lived 1845–1886","Built Neuschwanstein, the fairy-tale castle","And Linderhof and Herrenchiemsee","Richard Wagner's patron","Died, no one knows quite how, in Lake Starnberg"],"p":"Ludwig II of Bavaria"},
"empress-sisi": {"n":"Empress Sisi","a":["Elisabeth of Austria"],"c":["Empress of Austria and queen of Hungary","Lived 1837–1898; a Bavarian princess","Married the Emperor Franz Joseph at sixteen","Famous for her beauty, and her hair down to her ankles","Romy Schneider played her in the Sissi films","Assassinated in Geneva"],"p":"Empress Elisabeth of Austria"},
